#!/usr/bin/env python3
"""Generate the implementation report from recorded native test evidence."""
from pathlib import Path
import json,subprocess,datetime
root=Path(__file__).resolve().parents[1];docs=root/'Docs'
def read(name):return json.loads((docs/name).read_text())
native=read('christmas-stories-native-result.json');assert native['passed'],native['failures']
perf=read('christmas-stories-performance.json');baseline=read('christmas-stories-performance-baseline.json');memory=read('christmas-stories-memory.json');panel=read('christmas-stories-panel-result.json');window=read('christmas-stories-window-result.json')
assert panel['passed'] and window['passed'] and memory['passed'] and perf['passed'] and baseline['passed']
recordings=json.loads((docs/'Christmas-Stories-Demos/recordings.json').read_text());assert recordings['passed'] and len(recordings['items'])==8
core=(root/'.build/stories-core-final.log').read_text();assert '89 test methods; 0 assertion failures' in core
stories=[
('presentTheft','Йети крадёт подарок','Два гнома, йети; новые синие и зелёные коробки, мешочек.','Доставка → установка → выглядывание → подкрадывание → точный захват → погоня. Ветка A (70%): падение коробки, возврат, возмущённый гном. Ветка B (30%): побег; при временном режиме показана замена подарка. Число коробок меняется через единое завершение истории.'),
('lightRepair','Гномы чинят гирлянду','Два цветовых варианта общего рига; лестница, ящик, отвёртка, запасная лампочка и пояс.','Частичное приглушение гирлянды с тремя отдельно светящимися лампочками → приход бригады → установка → подъём по координатам ступеней → ремонт → небольшая реакция на лампу → свет → спуск → складывание. У маленькой ёлки ремонт с земли. Дополнительная регулировка мерцания во второй ветке. Пользовательский цвет и режим сохраняются.'),
('snowballExchange','Йети против снеговика','Существующий составной снеговик и йети, общий Projectile, снежные облачка; размер снежка в руке соответствует полёту.','Подход → сбор большого снежка → прицел → медленный полёт. Снеговик либо уклоняется в момент пролёта, либо получает попадание и поправляет шапку. Ответный бросок → падение йети → подъём → стряхивание → уход. Снеговик не уничтожается. Лёгкие следы йети затухают на снегу.'),
('snowmanBuild','Гномы лепят снеговика','Два гнома; три отдельных Snowball; существующие шары, лицо, пуговицы, шапка, шарф; новая морковка как переносимый предмет.','Постепенное катание и рост трёх шаров с расходом настоящего запаса SnowSurface. Руки следуют за точкой касания шара. Сборка через существующий SnowballSystem и отдельные дочерние узлы → нос → шапка/шарф → оживление → уход. Вторая ветка поправляет кривую шапку. Готовый снеговик входит в обычные механики приложения, лимит пять.'),
('treeShake','Йети трясёт ёлку','Йети с двумя точками контакта рук, два гнома, снежные шапочки; три реальные поверхности ветвей.','Подход → захват ствола → затухающая раскачка ёлки и украшений → отделение снега именно с ветвей → реакции гномов → последний ком на голову йети → стряхивание → восстановление украшений. Масса осыпавшегося снега возвращается в существующую физику и нижние сугробы; ёлка остаётся на месте.'),
('santaDrop','Санта теряет подарок','Существующие сани, Санта и мешок; две новые маленькие модели оленей с отдельными ногами; новая коробка.','Непрерывный полёт по дуге, наклон и покачивание → выпадение из мешка → баллистическое вращение и посадка → Санта улетает → два гнома подходят и одновременно берут коробку → совместная переноска с двумя контактами → установка у ёлки → поклон и уход. Событие привязано к одному экрану; коробки не дублируются.'),
('snowmanParty','Снежная вечеринка','Два гнома-декоратора, существующий снеговик; праздничная шапка, шарф, мини-гирлянда, звёздочка, маленькая лестница.','Приход с украшениями → при необходимости подъём для шапки → шапка и шарф → мягкое включение огоньков → танец и махание → поклон → уход. Во второй ветке гном роняет и поднимает звёздочку. Повторный праздник заменяет наряд, отмена возвращает прежний. При Keep story decorations сохраняется весь наряд, включая пять лампочек, после перезапуска.')]
lines=['SnowPlay — Christmas Stories 2.0','Отчёт реализации и проверки',datetime.datetime.now().isoformat(timespec='seconds'),'','Реализовано в существующем macOS-приложении SnowPlay и его локальном веб-пульте. Публичная браузерная сцена в корне репозитория отдельно не переписывалась.','']
for id,title,models,behaviour in stories:
 runs=[r for r in native['runs'] if r['id']==id];duration=' / '.join(f"{r['elapsed']:.2f}" for r in runs)
 lines.extend([title,'Модели: '+models,'Поведение: '+behaviour,'Проверка: обе ветки завершены в production-контроллерах AppKit/SpriteKit; длительности A/B: '+duration+' с. Три точки отмены, потеря цели, перекрытие окна и очистка резервирований проверены.',''])
lines.extend(['Общая архитектура','SnowCore/ChristmasStories.swift: типы историй, жизненный цикл, планировщик, атомарные резервирования, последовательности с ожиданием контакта/прибытия, проверка свободной области и разнесение тел.','SnowPlay/ChristmasStoryEngine.swift и ChristmasStoryRuntime.swift: один активный сценарий, общий движок шагов, точки захвата, парная переноска, общие снаряды, восстановление поз и объектов, ограниченные эффекты. Семь сценариев находятся в отдельных Story*.swift.','Использованы прежние LivingActor, SnowballSystem, Projectile, SnowSurface, AssetManager и настольные слои. На сцене не более трёх основных персонажей. Подарки и участники резервируются; в ходе истории новые невидимые окна ввода не создаются.','Следы — ограниченный пул из 32 лёгких визуальных отпечатков на основе существующего снежного ассета, затухание за 8 секунд. Новые SVG не конвертируются на каждом кадре.','15 новых исходных SVG и необязательный тихий WAV: Scripts/generate-story-assets.py. Исходные 63 SVG сохранены, всего 141 запись каталога и 146 подготовленных ресурсов с PNG 1x/2x.','',
'Пульт и автозапуск','Вкладка Stories: семь карточек, Play, Auto, объяснение недоступности, Random Stories, Rare / Normal / Often, Play Random Story и Stop. Дополнительные параметры спрятаны в Advanced Settings. Есть выбор зарезервированного края для значков рабочего стола. Подменю Christmas Stories добавлено в menu bar.','По умолчанию: Random Stories включён, Normal (30–45 минут), первая автоматическая история не раньше 10 минут подходящего активного времени. Rare: 60–90 минут, Often: 10–20 минут. Повтор подряд исключается, если есть альтернатива.','Сон, блокировка, пауза, полноэкранный режим и ручные занятия не ускоряют часы. Набор текста считается активным временем, но запуск ожидает тихого момента: 15 секунд после клавиши и 3 секунды после клика. Считываются только агрегированные интервалы активности, не клавиши и не содержимое окон. Системная политика опрашивается не чаще одного раза в секунду.','Звук, автоматическое создание снеговика и сохранение новых украшений по умолчанию выключены. Автоматическое создание требует отдельного разрешения в настройке приложения. Режим Focus и Reduce Motion исключают истории. На батарее они приостанавливаются, если это включено. Полноэкранные приложения всегда имеют приоритет настольного слоя.','',
'Результаты проверок',f"89 тестовых методов ядра — 0 ошибок. На этом Mac с Command Line Tools применён XCTestFallback, запускающий те же методы из Tests/SnowCoreTests; полный Xcode/XCTest-runner не установлен.",f"Нативные сценарии: {len(native['runs'])} полных прохождений, {native['cancellationRuns']} отмен, {native['windowInterruptionRuns']} прерываний контролируемой геометрией, {native['objectLossRuns']} удалений цели и изменение размеров экрана — без зависших историй/резервирований.",'Отдельно проверены максимум пять снеговиков, временные/постоянные подарки, многократный праздник без дублирования наряда, отмена поверх прежнего наряда и восстановление всего наряда после перезапуска.','Реальный WindowServer: отдельное собственное окно AppKit и production WindowObserver — все семь историй прерваны при перекрытии сцены. Проверены уровни ниже обычных окон и пропуск кликов.','WebKit: семь карточек, шесть вкладок, загрузка всех изображений, ширины 390/530 pt, недоступные состояния, частота, переключатели, запретные зоны и сохранение настроек. Прежние механики: пять снеговиков, перетаскивание, дуэль одним кликом, бросок курсором и уборка — smoke-тест пройден.',f"Память: {memory['loops']} цикла ({memory.get('perStory',{})}); все временные узлы и leases освобождены. RSS после прогрева: {memory['warmResidentMB']:.2f} → {memory['finalResidentMB']:.2f} MB. Изменение {memory['growthAfterWarmupMB']:.2f} MB не показывает роста в этой серии; это не полный Instruments Leaks scan.",'Восемь нативных видеодемонстраций: семь историй и обе концовки кражи. Это увеличенная изолированная сцена из настоящих production-узлов и рендереров AppKit/SpriteKit, а не запись личного рабочего стола пользователя.','',
'Производительность',f"Компьютер: {subprocess.check_output(['sysctl','-n','machdep.cpu.brand_string'],text=True).strip()}; macOS {subprocess.check_output(['sw_vers','-productVersion'],text=True).strip()}.",'Контрольная сцена: настоящее собственное нативное окно 1000×650, 1400 падающих частиц, ёлка и история с тремя персонажами. Release (-O).',f"SpriteKit update callbacks: {perf['spriteKit']['callbackFPS']:.2f}/с. Частота таймера/симуляции: {perf['simulationHz']:.2f} Гц. P95 шага симуляции: {perf['p95SimulationWorkMS']:.2f} мс; P95 интервала таймера: {perf['p95TimerIntervalMS']:.2f} мс.",f"CPU последнего секундного среза: без истории {baseline['cpuPercentOneCore']:.2f}% одного ядра; с историей {perf['cpuPercentOneCore']:.2f}% одного ядра. RSS: {baseline['residentMB']:.2f} / {perf['residentMB']:.2f} MB. Эти отдельные измерения содержат обычный системный шум; они не являются гарантией одинаковой нагрузки на других Mac.",'Частота вывода готовых кадров GPU/Metal presentation напрямую не измерялась. Зафиксированы callback FPS и время работы production-симуляции. Нельзя выдавать это за гарантированные 60 presented FPS на всех компьютерах.','',
'Ограничения и дальнейшая полировка','Свободная область резервируется консервативно: около 680×230 pt, для пролёта Санты — 680×320 pt. Если окно, Dock, другие модели или запретная зона занимают её, история не запускается. При появлении препятствия она завершается безопасно. Это намеренный способ сохранить обычную работу с Mac.','Focus / «Не беспокоить» учитывается через публичный INFocusStatusCenter, когда доступ уже разрешён macOS. При недоступном статусе он неизвестен; приватные API и чтение системных баз не применяются. Приложение не запрашивает лишние разрешения автоматически.','Публичные источники Apple: https://developer.apple.com/documentation/Intents/INFocusStatusCenter и https://developer.apple.com/documentation/coregraphics/cgeventsource/secondssincelasteventtype(_:eventtype:)','Физически несколько мониторов, все варианты Spaces/Mission Control, эксклюзивные полноэкранные игры и Intel Mac в этой сессии не проверялись. Отрицательные координаты и изменение границ проверены логикой/fixture. Реализация предназначена для существующего macOS-проекта; Windows-порт не создавался.','Снежинки и сугробы используют прежнюю физику. Реакции персонажей на облачко снега и одевание выполняются сценарно; это стилизованная 2D-анимация, а не тяжёлая симуляция ткани/скелета. Можно дальше расширять мимику гномов и библиотеку небольших вариантов поведения.','',
'Как посмотреть','1. Запустить dist/SnowPlay.app. Нажать снежинку menu bar и открыть Stories в обычном пульте.','2. Для кражи поставить ёлку и добавить подарки. Для ремонта выбрать Tree → Lights и включить Lights. Для перестрелки и вечеринки создать снеговика. Для тряски дождаться снега на ветвях. Для строительства включить Allow snowman creation и накопить снег.','3. Освободить подходящий участок рабочего стола. Неактивная кнопка Play показывает, чего не хватает. Нажать Play; Stop мягко возвращает согласованное состояние.','4. Для просмотра без подготовки рабочего стола открыть Docs/Christmas-Stories-Demos/index.html.','5. Разработчику: --story-developer показывает Ending A/B в Advanced Settings; автоматизированный принудительный прогон — python3 Scripts/run-app-check.py Scripts/ChristmasStoriesCheck.swift Scripts/ChristmasStoryFixture.swift (временный отдельный config, пользовательские настройки не меняет).','',
'Основные добавленные/изменённые файлы','Sources/SnowCore/ChristmasStories.swift; Configuration.swift.','Sources/SnowPlay/ChristmasStoryEngine.swift; ChristmasStoryRuntime.swift; ChristmasStoryCoordinator.swift; StoryPersistence.swift; семь файлов StoryPresentTheft, StoryLightRepair, StorySnowballExchange, StorySnowmanBuild, StoryTreeShake, StorySantaDrop, StorySnowmanParty.swift.','Coordinator.swift; Decorations.swift; FloorDecorations.swift; LivingModels.swift; LivingStories.swift; Interaction.swift; main.swift; Resources/Web/index.html, app.js, style.css.','Resources/SnowPlayAssets/World/story_*.svg, story_chime.wav, World/manifest.json и соответствующие Prepared PNG/индекс/каталог.','Tests/SnowCoreTests/ChristmasStoryTests.swift; Scripts/ChristmasStoryFixture.swift, ChristmasStoriesCheck.swift, StoriesPanelCheck.swift, StoryWindowSafetyCheck.swift, StoryPerformanceCheck.swift, StoryMemoryCheck.swift, RecordChristmasStories.swift, generate-story-assets.py, test-stories-panel.py и обновления существующих тестовых скриптов.','dist/SnowPlay.app, dist/SnowPlay-macOS.zip и dist/SHA256SUMS.txt; подробные JSON-результаты и демонстрации в Docs.'])
(docs/'Christmas-Stories-Report.txt').write_text('\n'.join(lines)+'\n')
print('Wrote Docs/Christmas-Stories-Report.txt')
